def VTask.leastOfBdd {P : ℤ → Prop} [DecidablePred P] (b : ℤ) (Hb : ∀ (z : ℤ), P z → b ≤ z) (Hinh : ∃ z, P z) : { lb // P lb ∧ ∀ (z : ℤ), P z → lb ≤ z } :=
let ⟨c, hc⟩ := Hinh in
let rec findLeast (k : ℤ) : ℤ × Bool :=
  if k ≥ c then (k, true)
  else match Decidable.em (P k) with
    | isTrue hk => (k, hk)
    | isFalse _ => findLeast (k + 1)
in let (lb, hb) := findLeast b in
  show { lb // P lb ∧ ∀ (z : ℤ), P z → lb ≤ z } from
    have hlb : P lb := hb,
    have hlbb : ∀ (z : ℤ), P z → lb ≤ z := fun z hp => 
      if z < lb then False.elim (lt_irrefl lb)
      else if z = lb then hp
      else by linarith [Hb z hp],
    { val := lb, property := And.intro hlb hlbb }
